package com.example.bandlink.controller; import com.example.bandlink.service.AdminUserService; import org.springframework.web.bind.annotation.*; import org.springframework.http.ResponseEntity;
@RestController @RequestMapping("/api/admin/users") public class AdminUserController{private final AdminUserService service;public AdminUserController(AdminUserService s){service=s;}@PatchMapping("/{id}/suspend") public ResponseEntity<Void> suspend(@PathVariable Long id){service.suspend(id);return ResponseEntity.noContent().build();}@PatchMapping("/{id}/unsuspend") public ResponseEntity<Void> unsuspend(@PathVariable Long id){service.unsuspend(id);return ResponseEntity.noContent().build();}}
